queries.query:
// Ventana de agregación (puede ser v.windowPeriod o fijo: 10s, 1m, etc.)
win = v.windowPeriod

from(bucket: "efd/autogen")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "lsst.sal.HVAC.coldGlycolChiller02" and
    (r._field == "compressor01Working" or
     r._field == "compressor02Working" or
     r._field == "compressor03Working" or
     r._field == "compressor04Working")
  )
  // convertir boolean a 0/1
  |> map(fn: (r) => ({ r with _value: if r._value then 1.0 else 0.0 }))
  // calcular promedio por ventana
  |> aggregateWindow(every: win, fn: mean, createEmpty: false)
  // pasar a porcentaje
  |> map(fn: (r) => ({ r with _value: r._value * 100.0 }))
  // reordenar tabla: una fila por tiempo, columnas por compresor
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> rename(columns: {
      compressor01Working: "mean_compressor01Working_pct",
      compressor02Working: "mean_compressor02Working_pct",
      compressor03Working: "mean_compressor03Working_pct",
      compressor04Working: "mean_compressor04Working_pct"
  })

