queries.query:
// Ventana (ajústala o deja v.windowPeriod)
win = v.windowPeriod

// AHUs a incluir
ahus = [
  "lsst.sal.HVAC.airHandlingUnit01Dome",
  "lsst.sal.HVAC.airHandlingUnit02Dome",
  "lsst.sal.HVAC.airHandlingUnit03Dome",
  "lsst.sal.HVAC.airHandlingUnit04Dome",
]

from(bucket: "efd/autogen")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
    r._field == "workingState" and contains(value: r._measurement, set: ahus)
  )
  // boolean -> 0/1
  |> map(fn: (r) => ({ r with _value: if r._value then 1.0 else 0.0 }))
  // promedio por ventana (proporción ON)
  |> aggregateWindow(every: win, fn: mean, createEmpty: false)
  // a porcentaje
  |> map(fn: (r) => ({ r with _value: r._value * 100.0 }))
  // tabla con columnas por AHU
  |> keep(columns: ["_time","_measurement","_value"])
  |> pivot(rowKey: ["_time"], columnKey: ["_measurement"], valueColumn: "_value")
  |> rename(columns: {
      "lsst.sal.HVAC.airHandlingUnit01Dome": "AHU01_workingState_on_pct",
      "lsst.sal.HVAC.airHandlingUnit02Dome": "AHU02_workingState_on_pct",
      "lsst.sal.HVAC.airHandlingUnit03Dome": "AHU03_workingState_on_pct",
      "lsst.sal.HVAC.airHandlingUnit04Dome": "AHU04_workingState_on_pct",
  })

